// 發送：本機 source → call 邊界
connector.Connect(microphone, mediaSender);
mediaSender.AttachToCall(call);

// 從 call 收到的媒體，成為本機資料圖的來源 → speaker
connector.Connect(mediaReceiver, speaker);
mediaReceiver.AttachToCall(call);

